from pathlib import Path
import csv,re,collections
from docx import Document
d=Document('C:/Users/User/Desktop/heat-mpi-REPORT.docx')
print('MAIN REPORT')
for p in d.paragraphs:
 if re.match(r'^(Part [0-4]|Appendix|.*pending.*|.*28 November.*)',p.text,re.I):print(p.text[:650])
n=Document('C:/Users/User/Desktop/Numerical_Solutions.docx')
tasks=[re.match(r'^Task (\d+\.\d+)',p.text)[1] for p in n.paragraphs if p.style.name=='Heading 2' and re.match(r'^Task (\d+\.\d+)',p.text)]
print('NUMERICAL TASKS',len(tasks),tasks)
for f in ['all_runs.csv','failed_attempts.csv','summary.csv','strong_scaling.csv','weak_scaling.csv']:
 p=Path('part4/results/consolidated')/f
 rows=list(csv.DictReader(p.open(encoding='utf-8')))
 print('\n',f,len(rows),'fields',list(rows[0]) if rows else [])
 if f=='all_runs.csv':
  print('statuses',collections.Counter(r['status'] for r in rows))
  print('sources',collections.Counter(r.get('source',r.get('sources','')) for r in rows))
  print('8192 distributed',[(r.get('path'),r.get('status')) for r in rows if r.get('N')=='8192' and int(r.get('P',0))>2])
 if f=='strong_scaling.csv':
  print('runs',sum(int(r['n_runs']) for r in rows),'complete groups',sum(int(r['n_runs'])>=3 for r in rows))
 if f=='weak_scaling.csv':
  for r in rows:print(r)
print('NEW CAMPAIGN LOGS',[str(x) for x in Path('.').glob('part*/results/campaign*')])
print('RAW node summaries',[(str(p),bool(re.search(r'^decomp=',p.read_text(errors='replace'),re.M))) for p in Path('part4/results').glob('*node*/*.log')])
